interface MetricsState {
  metricsById: Record<string, Metric>;
  setMetrics: (metrics: Metric[]) => void;
  getMetricById: (id: string) => Metric | undefined;
}

export const useMetricsStore = create<MetricsState>((set, get) => ({
  metricsById: {},
  setMetrics: (metrics) => set({ metricsById: Object.fromEntries(metrics.map(m => [m.id, m])) }),
  getMetricById: (id) => get().metricsById[id],
}));


