Here's how I'd structure `processPayment`:

typescript
export async function processPayment(
  amount: number,
  customerId: string
): Promise<{ success: true; transactionId: string } | { success: false; error: PaymentError }> {
  try {
    // Validate first
    if (amount <= 0) {
      return { success: false, error: { type: 'VALIDATION_ERROR', field: 'amount', message: 'Amount must be positive', retryable: false } };
    }

    // Stripe call
    const paymentIntent = await stripe.paymentIntents.create({ amount, customer: customerId });

    // Prisma call
    const transaction = await prisma.billingTransaction.create({
      data: { customerId, amount, stripePaymentIntentId: paymentIntent.id, status: 'PENDING' }
    });

    return { success: true, transactionId: transaction.id };
  } catch (err) {
    if (err instanceof Stripe.errors.StripeInvalidRequestError) {
      return { success: false, error: { type: 'STRIPE_API', code: err.code ?? 'UNKNOWN', retryable: false, message: 'Card declined' } };
    }
    if (err instanceof Stripe.errors.StripeRateLimitError) {
      return { success: false, error: { type: 'STRIPE_API', code: 'RATE_LIMIT', retryable: true, message: 'Please try again' } };
    }
    if (err instanceof Prisma.PrismaClientKnownRequestError) {
      // Log this internally
      console.error('Prisma error in processPayment:', err.code, err.meta);
      return { success: false, error: { type: 'DATABASE_ERROR', message: 'Unable to save transaction', retryable: true } };
    }
    // Unknown error
    return { success: false, error: { type: 'DATABASE_ERROR', message: 'An unexpected error occurred', retryable: true } };
  }
}


Specific catches first (Stripe errors), then Prisma, then fallback. This ensures you're handling known failure modes explicitly.

That HTTP status code mapping is spot-on. For Sentry logging, I'd recommend logging *all* failures to Sentry but with different severity levels:

typescript
// In pages/api/checkout.ts
export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { amount, customerId } = req.body;
  const result = await processPayment(amount, customerId);

  if (result.success) {
    return res.status(200).json({ transactionId: result.transactionId });
  }

  const error = result.error;
  const statusMap: Record<string, number> = {
    'STRIPE_API': error.retryable ? 503 : 402,
    'VALIDATION_ERROR': 400,
    'DATABASE_ERROR': 500,
    'INSUFFICIENT_FUNDS': 402
  };
  const status = statusMap[error.type];

  // Log to Sentry with context
  Sentry.captureException(new Error(`Payment failed: ${error.type}`), {
    level: error.retryable ? 'warning' : 'error',
    tags: { errorType: error.type, customerId },
    extra: { amount, message: error.message }
  });

  res.status(status).json({ error: error.message });
}


This way you've got audit trails in Sentry for billing disputes, but you're not spamming warnings for transient Stripe timeouts. The `customerId` tag makes it easy to trace issues per user in Metric Flow.

