kotlin
fun getWorkoutsWithCaching(
    userId: String,
    startDate: Long,
    endDate: Long
): Flow<List<Workout>> = combine(
    workoutDao.getWorkoutsByDateRange(userId, startDate, endDate), // Room
    firebaseDb.collection("users").document(userId)
        .collection("workouts")
        .whereGreaterThanOrEqualTo("timestamp", startDate)
        .whereLessThan("timestamp", endDate)
        .orderBy("timestamp", Query.Direction.DESCENDING)
        .snapshots()
        .map { snapshot -> snapshot.toObjects(Workout::class.java) } // Firestore
) { cached, fresh ->
    // Merge: Firestore takes precedence for updated items, cache fills gaps
    val freshMap = fresh.associateBy { it.id }
    val merged = (cached + fresh).distinctBy { it.id }
    merged.sortedByDescending { it.timestamp }
}.onEach { workouts ->
    // Persist Firestore updates back to Room
    workoutDao.upsertWorkouts(workouts)
}


