swift
struct Workout: Codable, Identifiable {
    let id: String
    let userId: String
    let exerciseName: String
    let timestamp: Date

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.userId = try container.decode(String.self, forKey: .userId)
        self.exerciseName = try container.decode(String.self, forKey: .exerciseName)
        self.timestamp = try container.decode(Date.self, forKey: .timestamp)
        self.id = ""  // Placeholder; set after decoding
    }
}


Then assign `workout.id = doc.documentID` in the listener. The first approach is simpler if you're using `Identifiable` for list rendering in SwiftUI.

