**Implementation in `internal/payment/middleware.go`**:
go
func (m *poolMonitor) UnaryInterceptor(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
    activeConns := getActiveConnections()  // from your instrumentation
    utilization := float64(activeConns) / float64(maxPoolSize)

    if utilization > 0.8 && utilization < 0.95 {
        backoffMs := time.Duration(rand.Intn(100)) * time.Millisecond
        time.Sleep(backoffMs)
    } else if utilization >= 0.95 {
        return nil, status.Error(codes.ResourceExhausted, "database connection pool at capacity")
    }
    return handler(ctx, req)
}


