**Architecture for resilience:**

In internal/config/origins_loader.go, implement a blocking startup check:

go
func LoadAllowedOrigins(ctx context.Context, redisClient *redis.Client, configMapData map[string]string) error {
    origins := parseOrigins(configMapData)

    if len(origins) == 0 {
        return errors.New("no origins loaded from ConfigMap")
    }

    // Attempt to load into Redis with timeout
    ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
    defer cancel()

    for _, origin := range origins {
        if err := redisClient.SAdd(ctx, "paystream:cors:origins", origin).Err(); err != nil {
            return fmt.Errorf("failed to populate redis origins: %w", err)
        }
    }

    // Verify at least one origin loaded
    count, err := redisClient.SCard(ctx, "paystream:cors:origins").Result()
    if err != nil || count == 0 {
        return errors.New("redis origins verification failed")
    }

    return nil
}


