export async function recordPayment(
  orderId: string,
  chargeId: string,
  amount: number
): Promise<void> {
  try {
    await prisma.$transaction(async (tx) => {
      const order = await tx.order.update({
        where: { id: orderId },
        data: { status: 'paid' },
      });

      await tx.payment.create({
        data: {
          orderId,
          chargeId,
