        throw new PaymentError(
          `Order ${orderId} not found during payment recording`,
          'order_not_found',
          false
        );
      }
      // Constraint violations, timeout errors, etc.
      throw new PaymentError(
        error.message,
        'database_error',
        true // Transient DB errors are retryable
      );
    }
    throw error;
  }
}


But here's the critical part: **you need a webhook handler for Stripe events** in `src/pages/api/webhooks/stripe.ts`. This is your reconciliation. Stripe will retry webhook delivery for 3 days, so even if your `recordPayment()` fails, you can replay the webhook and succeed:

typescript
export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return res.status(405).end();

  const event = req.body as Stripe.Event;

  try {
    if (event.type === 'charge.succeeded') {
      const charge = event.data.object as Stripe.Charge;
      await recordPayment(
        charge.metadata.orderId,
        charge.id,
        charge.amount / 100
      );
    }
    res.status(200).json({ received: true });
  } catch (error) {
    logger.error('Webhook processing failed', { eventId: event.id, error });
    // Return 400 to tell Stripe to retry
    res.status(400).json({ error: 'Processing failed' });
  }
}


This way, your database write failures don't leave orphaned charges—Stripe will retry the webhook, and you get eventual consistency without a nightly reconciliation job.

The `ETIMEDOUT` errors are likely network-level timeouts happening *before* the Stripe SDK's retry logic kicks in. When you hit a raw socket timeout, the SDK can't retry because the connection itself failed.

Here's what's happening: Vercel's cold starts can cause connection delays to external services. By the time the socket connects to Stripe's API, you might already be deep into that 30s window.

**Two changes I'd make to `src/config/stripe.ts`:**

