export const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2023-10-16',
  maxNetworkRetries: 3,
  timeout: 60000, // Increase to 60s for Vercel cold starts
  httpClient: new Stripe.createFetchHttpClient(), // Use fetch instead of node's http
