But more importantly, **wrap your Stripe calls with exponential backoff in `src/services/payment/processPayment.ts`:**

typescript
async function callStripeWithRetry<T>(
  fn: () => Promise<T>,
  maxAttempts = 4
): Promise<T> {
  let lastError: Error | null = null;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error as Error;
      const isNetworkError = error instanceof Stripe.errors.StripeAPIConnectionError;
      if (!isNetworkError || attempt === maxAttempts - 1) throw error;

      const delayMs = Math.pow(2, attempt) * 1000 + Math.random() * 1000;
      await new Promise(resolve => setTimeout(resolve, delayMs));
      logger.warn('Stripe call failed, retrying', {
        attempt: attempt + 1,
        delayMs,
        errorMessage: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  }
  throw lastError;
}

export async function processPayment(orderId: string, amount: number): Promise<PaymentResult> {
  return callStripeWithRetry(() =>
    stripe.charges.create({
      amount: Math.round(amount * 100),
      currency: 'usd',
      idempotency_key: orderId
    })
  );
}


This gives you exponential backoff on top of the SDK's retries: 1s, 2s, 4s, 8s (plus jitter to avoid thundering herd). The idempotency_key ensures you're safe from double-charges even with these retries.

