useEffect(() => {
  const subscription = client.subscribeToTransactions({
    accountId: userId,
    batchSize: 100
  });

  subscription.on('data', (transaction) => {
    setTransactions(prev => [...prev, transaction]);
  });

  subscription.on('error', (err) => {
    console.error('Stream error:', err);
